import{_ as s,o as t,c as a,a2 as o}from"./chunks/framework.CdvW4CUT.js";const u=JSON.parse('{"title":"我是怎么搭建这个博客的","description":"","frontmatter":{},"headers":[],"relativePath":"posts/build-this-blog.md","filePath":"posts/build-this-blog.md","lastUpdated":1792903128000}'),i={name:"posts/build-this-blog.md"};function d(l,e,n,p,c,r){return t(),a("div",null,[...e[0]||(e[0]=[o(`<h1 id="我是怎么搭建这个博客的" tabindex="-1">我是怎么搭建这个博客的 <a class="header-anchor" href="#我是怎么搭建这个博客的" aria-label="Permalink to &quot;我是怎么搭建这个博客的&quot;">​</a></h1><blockquote><p>2026-10-25</p></blockquote><p>需求很简单:一个属于自己的技术博客,免费托管,一条命令就能发布。这篇文章记录完整的搭建过程,包括一次被 GitHub 拒绝的推送。也算给这个博客的叙事风格打个样:<strong>问题背景 → 方案选型 → 实施过程 → 踩的坑 → 总结</strong>。</p><h2 id="问题背景" tabindex="-1">问题背景 <a class="header-anchor" href="#问题背景" aria-label="Permalink to &quot;问题背景&quot;">​</a></h2><p>想在 GitHub Pages 上要一个博客,约束条件:</p><ul><li>免费、稳定,内容在自己手里(可随时迁移)</li><li>写作就是写 Markdown,不要花哨的后台</li><li>支持中文、本地搜索、深色模式这些基本体验</li></ul><h2 id="方案选型-vitepress-还是-hugo" tabindex="-1">方案选型:VitePress 还是 Hugo <a class="header-anchor" href="#方案选型-vitepress-还是-hugo" aria-label="Permalink to &quot;方案选型:VitePress 还是 Hugo&quot;">​</a></h2><p>主流选择就这两个,对比下来:</p><table tabindex="0"><thead><tr><th></th><th>VitePress</th><th>Hugo</th></tr></thead><tbody><tr><td>运行环境</td><td>Node.js</td><td>单个二进制</td></tr><tr><td>定制方式</td><td>Vue 组件</td><td>Go 模板</td></tr><tr><td>中文文档</td><td>官方支持好</td><td>主题文档居多</td></tr><tr><td>本地搜索</td><td>内置</td><td>依赖主题</td></tr></tbody></table><p>我的机器上 Node 是现成的,前端技术栈也更熟,出问题能自己看源码调试,所以选了 <strong>VitePress</strong>。如果是不写前端、又想极简的人,Hugo 更省事——这是口味问题,不是优劣问题。</p><h2 id="实施过程" tabindex="-1">实施过程 <a class="header-anchor" href="#实施过程" aria-label="Permalink to &quot;实施过程&quot;">​</a></h2><h3 id="_1-脚手架" tabindex="-1">1. 脚手架 <a class="header-anchor" href="#_1-脚手架" aria-label="Permalink to &quot;1. 脚手架&quot;">​</a></h3><p>没用 <code>npm create vitepress@latest</code>,因为交互式命令行在自动化环境里不好使。手写脚手架反而更清楚,总共就四个东西:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>docs/</span></span>
<span class="line"><span>  .vitepress/config.ts   # 站点配置</span></span>
<span class="line"><span>  index.md               # 首页</span></span>
<span class="line"><span>  posts/                 # 文章目录</span></span>
<span class="line"><span>package.json</span></span></code></pre></div><p><code>package.json</code> 里加三个脚本:<code>dev</code>(本地预览)、<code>build</code>(构建)、<code>deploy</code>(发布,后面细说)。</p><p><code>config.ts</code> 里配置了中文语言、导航栏、按 <code>/posts/</code> 前缀分组的侧边栏,以及内置的本地搜索(把 UI 文案翻译成了中文)。</p><h3 id="_2-部署-一次被拒的推送" tabindex="-1">2. 部署:一次被拒的推送 <a class="header-anchor" href="#_2-部署-一次被拒的推送" aria-label="Permalink to &quot;2. 部署:一次被拒的推送&quot;">​</a></h3><p>第一版方案是最&quot;标准&quot;的:写一个 GitHub Actions 工作流,push 到 <code>main</code> 时 CI 自动构建、自动发布,本地只管写 Markdown。</p><p>工作流写好,<code>git push</code>,被远端拒绝了:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>! [remote rejected] main -&gt; main (refusing to allow an OAuth App to create</span></span>
<span class="line"><span>  or update workflow \`.github/workflows/deploy.yml\` without \`workflow\` scope)</span></span></code></pre></div><p>原因:我是用 GitHub CLI(<code>gh</code>)登录的,它的 OAuth token 只有 <code>repo</code> 等基础权限,<strong>没有 <code>workflow</code> 权限</strong>。GitHub 规定:经 OAuth 授权的令牌如果想创建或修改 workflow 文件,必须显式带上 <code>workflow</code> scope——这是 2021 年 Codecov 供应链事件之后加的防护。</p><p>补授权只要一条命令(<code>gh auth refresh -s workflow</code>,浏览器里点一次确认),但当时想走通无人工介入的路径,于是换了个不需要任何额外权限的方案:</p><h3 id="_3-最终方案-gh-pages-分支部署" tabindex="-1">3. 最终方案:gh-pages 分支部署 <a class="header-anchor" href="#_3-最终方案-gh-pages-分支部署" aria-label="Permalink to &quot;3. 最终方案:gh-pages 分支部署&quot;">​</a></h3><p>思路很朴素,分两支:</p><ul><li><code>main</code> 分支:只放源码(Markdown、配置)</li><li><code>gh-pages</code> 分支:只放构建产物(<code>vitepress build</code> 的输出)</li></ul><p>本地跑 <code>npm run deploy</code>,一条命令完成&quot;构建 + 把产物推到 <code>gh-pages</code> 分支&quot;,再把 GitHub Pages 的来源指向 <code>gh-pages</code> 分支,线上就生效了。推送纯静态文件只需要 <code>repo</code> 权限,正好绕开了上面那个限制。</p><p>把 Pages 来源从 workflow 模式切回分支模式,用 API 一次搞定:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">gh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> api</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> PUT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repos/66ou66/66ou66.github.io/pages</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --input</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> -</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;EOF&#39;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">{&quot;source&quot;: {&quot;branch&quot;: &quot;gh-pages&quot;, &quot;path&quot;: &quot;/&quot;}}</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">EOF</span></span></code></pre></div><h2 id="踩的坑" tabindex="-1">踩的坑 <a class="header-anchor" href="#踩的坑" aria-label="Permalink to &quot;踩的坑&quot;">​</a></h2><ol><li><strong>OAuth token 缺 <code>workflow</code> scope 会拒推</strong>。不是所有 <code>git push</code> 失败都是网络问题,看清 <code>remote rejected</code> 的具体文案,它一般把原因写得明明白白。</li><li><strong>Pages 的&quot;来源&quot;必须和部署方式匹配</strong>。GitHub Pages 支持两种发布方式:从分支读静态文件,或走 GitHub Actions。用 API 建站点时默认给了 workflow 模式,切成分支部署就要显式改回去,不然 <code>gh-pages</code> 分支推上去网站也是 404。</li><li><strong><code>cleanUrls</code> 不能开</strong>。VitePress 的 <code>cleanUrls</code> 选项可以把 URL 变成不带 <code>.html</code> 的形式,但它依赖服务器做 URL 重写,GitHub Pages 不做,开了之后搜索结果点进去就是 404。所以站内链接老老实实带 <code>.html</code>。</li><li><strong>(留给以后)</strong> 如果哪天切回 Actions 方案,记得工作流里 checkout 要加 <code>fetch-depth: 0</code>,否则浅克隆拿不到 git 历史,页面底部的&quot;最后更新&quot;时间算不出来。</li></ol><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>整个搭建不到一小时,其中&quot;被拒的推送&quot;到&quot;想清楚换方案&quot;占了十分钟——事后看,这次波折比我预想的任何顺利流程都值得写。</p><p>以后写文章的流程就是:<code>npm run dev</code> 预览 → <code>docs/posts/</code> 下写 Markdown → 侧边栏加一条 → <code>npm run deploy</code>,一分钟后线上可见。</p><p>后续想做的事:</p><ul><li>[ ] 接入 <a href="https://giscus.app/" target="_blank" rel="noreferrer">giscus</a>,用 GitHub Discussions 做评论</li><li>[ ] 生成 sitemap,提交给搜索引擎</li><li>[ ] 加一个 RSS 订阅地址</li><li>[ ] 哪天想通了,跑一次 <code>gh auth refresh -s workflow</code>,升级成 push 即部署</li></ul><p>这些做完了再写一篇。</p>`,36)])])}const g=s(i,[["render",d]]);export{u as __pageData,g as default};
